arrived = [1, 3, 4, 5]   # 报文段到达情况：第 2 个丢失
expected = 2             # 接收方期望的下一个报文段
dup = 0                  # 重复确认计数
for seg in arrived:
    if seg != expected:
        dup = dup + 1    # 失序到达，接收方重复确认 expected
    if dup == 3:
        print('收到 3 个重复确认，快速重传报文段 ' + str(expected))
        break
print('模拟结束')
